arguments.command:
cd /app && psql -U consul -h /var/lib/postgresql/sockets -d consul_development -c "
-- 1. Non-empty tables
DO \$\$
DECLARE
  r RECORD;
  cnt BIGINT;
BEGIN
  FOR r IN SELECT tablename FROM pg_tables WHERE schemaname = 'public' ORDER BY tablename LOOP
    EXECUTE format('SELECT count(*) FROM public.%I', r.tablename) INTO cnt;
    IF cnt > 0 THEN
      RAISE NOTICE 'TABLE % : % rows', r.tablename, cnt;
    END IF;
  END LOOP;
END
\$\$;
" -c "
-- 2. Check all *_type columns for any remaining values
DO \$\$
DECLARE
  r RECORD;
  vals TEXT;
BEGIN
  FOR r IN
    SELECT table_name, column_name
    FROM information_schema.columns
    WHERE table_schema = 'public' AND column_name LIKE '%_type' AND data_type IN ('character varying', 'text')
    ORDER BY table_name, column_name
  LOOP
    EXECUTE format('SELECT string_agg(DISTINCT quote_literal(%I), '', '') FROM public.%I WHERE %I IS NOT NULL', r.column_name, r.table_name, r.column_name) INTO vals;
    IF vals IS NOT NULL THEN
      RAISE NOTICE 'POLY %.% : %', r.table_name, r.column_name, vals;
    END IF;
  END LOOP;
END
\$\$;
" -c "
-- 3. Check tags, web_sections, users.notifications_count
SELECT id, name, taggings_count, debates_count, budget_investments_count, legislation_proposals_count, legislation_processes_count FROM tags ORDER BY id;
SELECT id, name FROM web_sections ORDER BY id;
SELECT id, username, notifications_count FROM users WHERE notifications_count != 0 ORDER BY id;
SELECT count(*) AS settings_count FROM settings;
" -c "
-- 4. Check schema objects mentioning proposal/dashboard/link/digest/emailed/related
SELECT table_name FROM information_schema.tables WHERE table_schema = 'public' AND table_name ~* 'proposal|dashboard|link' ORDER BY table_name;
SELECT table_name, column_name FROM information_schema.columns WHERE table_schema = 'public' AND column_name ~* 'proposal|dashboard|digest|emailed|^related_(type|id)$' ORDER BY table_name, column_name;
SELECT sequencename FROM pg_sequences WHERE schemaname = 'public' AND sequencename ~* 'proposal|dashboard|link' ORDER BY sequencename;
" 2>&1

